        Chat.load(CHAT).check_in(is_busy=True, name=name)
except Exception as failure:
    failures.append(failure)

const opened = await app.open()
if (!opened) return
if (opened.status !== 'running') {
  this.store.toast(`The ${opened.label} app is ${opened.status}: open it from the chat bar's status row, which starts it for that chat.`, true)
  return
}
const page = new URL(opened.url)
page.searchParams.set(PROJECT_QUERY, project)
if (chat) page.searchParams.set(CHAT_QUERY, chat)
this.openWindow(page.toString())

if self._keyword:
    return self._keyword[0].upper() + self._keyword[1:].lower()
value = getattr(self.step_type, "value", self.step_type)
return str(value).capitalize()

if self._keyword:
    return self._keyword.casefold() in ("and", "but")
return self.text.strip().startswith(("And ", "But "))

found: List[str] = []
for concept in self.concepts or []:
    token = concept.strip()
    if token and token[0].isupper() and token not in found:
        found.append(token)
return found

parent = self.parent
if not isinstance(parent, Epic):
    return 0
if not isinstance(parent.parent, Epic):
    return 0
return parent.depth + 1
